def print_board(board: List[int]) -> None:
    """Print the TicTacToe board with symbols (-, X, O)."""
    symbols = {0: '-', 1: 'X', 2: 'O'}
    for i in range(0, 9, 3):
        row = [symbols[val] for val in board[i:i+3]]
        print(" ".join(row))
    print("\n")

def random_board() -> List[int]:
    """Generate a random TicTacToe board (9 cells, values 0/1/2)."""
    board = [random.choice([0, 1, 2]) for _ in range(9)]
    print("BOARD GENERATED\n")
    print_board(board)
    return board

def create_context():
    from jam.finality.finality import Finality
    from jam.state.state import state
    from jam.settings import settings

    lookup_anchor = Finality.load_final(settings.main_db)
    anchor = Finality.load_latest(settings.main_db)

    if len(state.beta.h):
        anchor_beta: BlockHistory = state.beta.h[-1]

        print("CHECKING LATEST BLOCK FROM FINALITY AND BETA!!")
        matches = anchor_beta.header_hash == anchor.header.hash()
        print("RESULT: ", "Success" if matches else "Failure", "\n")

        if not matches:
            print("NOW NOTHING CAN BE DONE!!")
            raise ValueError("Latest block and beta state's last block don't match")

        context = RefineContext.empty()
        context.anchor = anchor_beta.header_hash
        context.state_root = anchor_beta.state_root
        context.beefy_root = anchor_beta.beefy_root
        context.lookup_anchor = lookup_anchor.header.hash()
        context.lookup_anchor_slot = lookup_anchor.header.slot
        print("YAY!!")

        return context

    else:
        raise ValueError("No finalized block found!")

AUTH_HOST = ServiceId(0)
def create_package(state, service_id, code_hash):

    wp: WorkPackage = create_dummy_package()

    wp.authorization = Bytes(b"")
    wp.context = create_context()
    wp.auth_code_host = AUTH_HOST
    print("TEST 1")
    wp.authorizer.code_hash = OpaqueHash(bytes.fromhex("39b65b7817afe98e7b7b5440a9d2ed4ce1a593a8f954afd9ad3d63159996d62a"))
    wp.authorizer.params = Bytes(b"")
    print("TEST 2")
    items = WorkItems([])
    for i in range(8):
        board = random_board()
        payload = Bytes(bytes(board))

        item = WorkItem(
            service_id,
            code_hash,
            Gas(1_000),
            Gas(1_000),
            U16(0),
            payload,
            ImportSpecs([]),
            ExtrinsicSpecs([]),
        )

        items.append(item)

    wp.items = items
    # _, pc = wp.m_c(state.delta)

    # print("CODE LEN", len(pc))

    return wp

